const IC={
 menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 6h16M4 12h16M4 18h16"/></svg>',
 back:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5l-7 7 7 7"/></svg>',
 bell:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 8a6 6 0 1 1 12 0c0 7 3 8 3 8H3s3-1 3-8"/><path d="M10 20a2 2 0 0 0 4 0"/></svg>',
 chev:'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="m9 6 6 6-6 6"/></svg>'};
const BAN='<div class="banner">Demo workspace · sample data, no live integrations</div>';
S.persona='lead';S.unread=3;
const club=()=>S.persona==='admin'?'CUNY SPS · Student Life':'Artificial Intelligence Club';
function hdr(title,back,ctx){return '<header class="top">'+(back?'<button class="icon" data-back="'+back+'" aria-label="Back">'+IC.back+'</button>':'<button class="icon" data-menu aria-label="Open menu">'+IC.menu+'</button>')+
 '<div class="ttl"><div class="ctx">'+(ctx||club())+'</div><div class="title">'+title+'</div></div>'+
 (back?'':'<button class="icon" data-go="notifications" aria-label="Notifications'+(S.unread?', '+S.unread+' unread':'')+'">'+IC.bell+(S.unread?'<span class="dot"></span>':'')+'</button>')+'</header>'+BAN}
function chips(group,items,cur){return '<div class="chips mb12" role="group">'+items.map(([k,l])=>'<button class="chip" aria-pressed="'+(k===cur)+'" data-chip="'+group+'" data-v="'+k+'">'+l+'</button>').join('')+'</div>'}
function stats(arr){return '<div class="statgrid">'+arr.map(([n,l])=>'<div class="stat"><b>'+n+'</b><span>'+l+'</span></div>').join('')+'</div>'}
function intro(h,sub,btn){return '<div class="pad" style="padding-bottom:10px"><div class="row" style="align-items:flex-start"><div><h1 class="h1">'+h+'</h1>'+(sub?'<p class="cap">'+sub+'</p>':'')+'</div>'+(btn||'')+'</div></div>'}
function lrow(o){return '<button class="lrow" '+(o.act||'')+'>'+(o.av?'<span class="avatar" style="background:'+(o.avc||'var(--thistle)')+'">'+o.av+'</span>':'')+'<span class="t"><b>'+o.t+'</b>'+(o.s?'<span class="cap">'+o.s+'</span>':'')+(o.x?'<span class="cap" style="display:block">'+o.x+'</span>':'')+'</span>'+(o.pill?'<span class="pill '+(o.pc||'')+'">'+o.pill+'</span>':'')+(o.nochev?'':'<span class="chev">'+IC.chev+'</span>')+'</button>'}
function bars(vals,labels){const m=Math.max(...vals,1);return '<div class="bars" role="img" aria-label="Bar chart: '+labels.map((l,i)=>l+' '+vals[i]).join(', ')+'">'+vals.map((v,i)=>'<div class="bar"><i style="height:'+Math.max(4,Math.round(v/m*100))+'%"></i><span>'+labels[i]+'</span></div>').join('')+'</div>'}
function last30(){const e=new Date(2026,10,TODAY),s=new Date(e);s.setDate(e.getDate()-29);const f=d=>d.toLocaleDateString('en-US',{month:'short',day:'numeric'});return f(s)+' – '+f(e)+', 2026'}
function ok(t){return '<span class="pill mint">'+t+'</span>'}
const now=()=>new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
function audit(actor,action,target){S.audit.unshift({t:'Nov 18 · '+now(),actor,action,target})}
const TODAY=(()=>{const x=new Date();return x.getFullYear()===2026&&x.getMonth()===10?x.getDate():18})();
function dayOf(){const v=($('#date')||{}).value||'';const m=v.match(/^2026-11-(\d\d)$/);return S.when==='now'?TODAY:(m?+m[1]:null)}

