 ics(){try{navigator.clipboard.writeText('https://hub.example.edu/ics/ai-club.ics').then(()=>toast('Calendar feed link copied (sample link)'),()=>toast('Calendar feed: hub.example.edu/ics/ai-club.ics (sample)'))}catch(e){toast('Calendar feed: hub.example.edu/ics/ai-club.ics (sample)')}},
 logAtt(){openSheet('<h2 class="h2 mb8">Log attendance</h2><div class="field"><label class="label" for="la-ev">Event</label><select id="la-ev">'+EVENTS.slice(0,3).map(e=>'<option value="'+e.id+'">'+e.title+'</option>').join('')+'</select></div><div class="field"><label class="label" for="la-n">Verified check-ins</label><input id="la-n" type="number" inputmode="numeric" pattern="[0-9]*" min="0" value="30"></div><button class="btn pri block" id="la-go">Save</button>');$('#la-go').onclick=()=>{S.attLog[$('#la-ev').value]=+$('#la-n').value||0;closeAll();toast('Attendance logged');render()}},
 csv(){toast('Exports download in the real app. This demo can’t save files.')},
 remToggle(){S.rem.on=!S.rem.on;render()},
 sweep(){if(!S.rem.on){toast('Turn on auto-reminders first');return}const q=S.rem.queue.filter(x=>x.st==='Queued');q.forEach(x=>x.st='Sent');audit('System','Publishing','REMINDER_SWEEP · '+q.length+' events');toast(q.length?q.reduce((n,x)=>n+x.n,0)+' reminder emails sent':'Nothing due in the next 24 hours');render()},
 telemetry(){openSheet('<h2 class="h2 mb12">Delivery log</h2><div class="card">'+lrow({t:'MSA Community Tea & Study Circle',s:'2 delivered · 0 bounced · Nov 17',nochev:true})+lrow({t:'Fallback outbox',s:'Not used · institutional email transport configured',nochev:true})+'</div>')},
 newThread(){openSheet('<h2 class="h2 mb8">Start a thread</h2><div class="field"><label class="label" for="nt-t">Title</label><input id="nt-t" placeholder="What do you want to discuss?"></div><div class="field"><label class="label" for="nt-k">Type</label><select id="nt-k"><option>Question</option><option>Discussion</option></select></div><button class="btn pri block" id="nt-go">Post thread</button>');$('#nt-go').onclick=()=>{const t=$('#nt-t').value.trim();if(!t)return toast('Add a title');S.threads.unshift({id:Date.now(),tags:[$('#nt-k').value],t,by:'Aisha Rahman',replies:[]});closeAll();render()}},
