 decline(v){const p=S.pending.splice(v,1)[0];toast('Request from '+p.n+' declined');render()},
 decide(v){const [id,d]=v.split('|');const r=S.reqs.find(x=>x.id===id);if(d==='approve'){r.step=3;r.st='Approved for setup'}else if(d==='info'){r.st='More information required'}else{r.st='Declined'}audit('Dr. Elena Vance','Governance','ACCOUNT_REQUEST_DECISION · '+id+' · '+r.st);toast(id+': '+r.st);render()},
 doc(v){toast(v+' opens as a file in the real app')},
 join(v){const c=S.clubs[v];if(!S.joined[v]){S.joined[v]=true;toast('Request sent to '+c.n+'’s leads');render();return}
  openSheet('<h2 class="h2 mb8">Cancel your request?</h2><p class="cap mb16">Your request to join '+esc(c.n)+' is waiting for the club’s leads.</p><button class="btn pri block mb8" id="jn-cancel">Cancel request</button><button class="btn sec block" id="jn-keep">Keep request</button>');
  $('#jn-keep').onclick=closeAll;$('#jn-cancel').onclick=()=>{S.joined[v]=false;closeAll();toast('Request cancelled');render()}},
