  openSheet('<h2 class="h2 mb12">Edit event</h2><div class="field"><label class="label" for="ee-t">Event name</label><input id="ee-t" value="'+esc(e.title)+'"></div><div class="two"><div class="field"><label class="label" for="ee-d">Date</label><input id="ee-d" type="date" min="'+(()=>{const n=new Date();return n.getFullYear()+'-'+p(n.getMonth()+1)+'-'+p(n.getDate())})()+'" value="'+dv+'"></div><div class="field"><label class="label" for="ee-h">Time</label><input id="ee-h" type="time" value="'+tv+'"></div></div><div class="field"><label class="label" for="ee-w">Where</label><input id="ee-w" value="'+esc(wh)+'"></div><div class="card pad mb12"><div class="row"><span>Tell the '+n+' people going</span><button class="switch" role="switch" aria-checked="true" id="ee-n" aria-label="Notify people going"></button></div></div><button class="btn pri block" id="ee-save">Save changes</button>');
